# --- 2차 캐시를 써 보면 ---

@Entity
@Cache(usage = CacheConcurrencyStrategy.READ_ONLY)
public class Item { ... }

em.find(Item.class, 2L);
#   Hibernate: select ... from item where item_id=?

em.clear();
em.find(Item.class, 2L);
#   (쿼리 없음)

#   2차 캐시가 맞았다

em.createQuery("select i from Item i", Item.class).getResultList();
#   Hibernate: select ... from item i1_0

#   JPQL 은 그대로 나간다

#   목록 조회에는 안 듣는다

